import{_ as t,c as e,o,ag as r}from"./chunks/framework._xRlcm3f.js";const p=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1790228279000}'),i={name:"guide/faq.md"};function l(d,a,s,h,n,c){return o(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><p>这一页收集配置与发布过程中最常见的疑问。按主题分组，遇到问题先在这里找。</p><h2 id="安装与更新" tabindex="-1">安装与更新 <a class="header-anchor" href="#安装与更新" aria-label="Permalink to &quot;安装与更新&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">建议先卸载再安装</p><p>本插件迭代频繁。为避免程序缓存导致不可预知的问题，更新时请<strong>先卸载、再重新安装</strong>，不要直接覆盖。</p></div><h3 id="配置异常导致插件完全不可用怎么办" tabindex="-1">配置异常导致插件完全不可用怎么办 <a class="header-anchor" href="#配置异常导致插件完全不可用怎么办" aria-label="Permalink to &quot;配置异常导致插件完全不可用怎么办&quot;">​</a></h3><p>备份 <code>[workspace]/data/storage/syp/sy-p-plus-cfg.json</code>，然后删除它——这个文件会在首次使用时自动重新初始化。</p><p>操作时最好<strong>先关闭思源</strong>，删除配置后再打开，防止思源运行中已读取旧数据又把配置覆盖回去。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>插件能正常使用时<strong>不要</strong>做这个操作。</p></div><h2 id="平台配置" tabindex="-1">平台配置 <a class="header-anchor" href="#平台配置" aria-label="Permalink to &quot;平台配置&quot;">​</a></h2><h3 id="github-gitlab-系平台有什么特别要求" tabindex="-1">GitHub / GitLab 系平台有什么特别要求 <a class="header-anchor" href="#github-gitlab-系平台有什么特别要求" aria-label="Permalink to &quot;GitHub / GitLab 系平台有什么特别要求&quot;">​</a></h3><p>只支持<strong>源码部署</strong>。请确认你的仓库里存的是可构建的源码目录结构，而不是已构建的产物。</p><h3 id="知乎和-csdn-应该选哪种发布格式" tabindex="-1">知乎和 CSDN 应该选哪种发布格式 <a class="header-anchor" href="#知乎和-csdn-应该选哪种发布格式" aria-label="Permalink to &quot;知乎和 CSDN 应该选哪种发布格式&quot;">​</a></h3><p>这两个平台目前<strong>只能选择 HTML 模式</strong>发布。在平台配置里把「发布格式」设为 HTML 即可正常使用。</p><h3 id="知乎的专栏怎么获取" tabindex="-1">知乎的专栏怎么获取 <a class="header-anchor" href="#知乎的专栏怎么获取" aria-label="Permalink to &quot;知乎的专栏怎么获取&quot;">​</a></h3><ol><li>打开知乎个人主页，找到你的用户名。</li><li>在插件配置页的「用户名」字段填入它。</li><li>点「验证」，通过后即可从专栏列表里选择。</li></ol><h3 id="csdn-知乎过一段时间提示「需要登录」" tabindex="-1">CSDN / 知乎过一段时间提示「需要登录」 <a class="header-anchor" href="#csdn-知乎过一段时间提示「需要登录」" aria-label="Permalink to &quot;CSDN / 知乎过一段时间提示「需要登录」&quot;">​</a></h3><p>这通常是 Cookie 过期。以 CSDN 为例：</p><ol><li>安装「网页视图」插件，在思源内打开 CSDN 首页并<strong>退出登录</strong>。</li><li>回到插件配置页，重新授权。</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>必须在思源的网页视图里退出登录才有效，在外部浏览器退出不会同步。</p></div><h3 id="知乎授权报-code-40362-或提示请求异常" tabindex="-1">知乎授权报 <code>{&quot;code&quot;:40362}</code> 或提示请求异常 <a class="header-anchor" href="#知乎授权报-code-40362-或提示请求异常" aria-label="Permalink to &quot;知乎授权报 `{&quot;code&quot;:40362}` 或提示请求异常&quot;">​</a></h3><p>知乎已限制在 Electron 内登录，因此<strong>只能复制 Cookie</strong>。请升级到最新版插件，删除该平台账号后重新导入。</p><h3 id="cors-代理怎么配置" tabindex="-1">CORS 代理怎么配置 <a class="header-anchor" href="#cors-代理怎么配置" aria-label="Permalink to &quot;CORS 代理怎么配置&quot;">​</a></h3><p>见插件内的「CORS 代理配置指南」。如果平台配置异常，先确认思源地址与端口填写正确（默认 <code>127.0.0.1</code>，本地使用）。</p><h3 id="docker-版初次打开显示不正常" tabindex="-1">Docker 版初次打开显示不正常 <a class="header-anchor" href="#docker-版初次打开显示不正常" aria-label="Permalink to &quot;Docker 版初次打开显示不正常&quot;">​</a></h3><p>检查「偏好设置」里的思源地址是否包含端口。Docker 环境下填错地址会导致读不到数据。</p><h2 id="发布行为" tabindex="-1">发布行为 <a class="header-anchor" href="#发布行为" aria-label="Permalink to &quot;发布行为&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">每次发布都会覆盖正文</p><p>发布工具每次都会获取思源中<strong>最新编辑的正文</strong>进行覆盖发布。因此<strong>不要在平台上直接修改正文</strong>，改动会在下次发布时被覆盖。</p></div><h3 id="各平台的图片是怎么处理的" tabindex="-1">各平台的图片是怎么处理的 <a class="header-anchor" href="#各平台的图片是怎么处理的" aria-label="Permalink to &quot;各平台的图片是怎么处理的&quot;">​</a></h3><table tabindex="0"><thead><tr><th>平台类型</th><th>图片处理方式</th></tr></thead><tbody><tr><td>知乎、CSDN、微信公众号</td><td>使用平台自带上传</td></tr><tr><td>Notion、语雀、掘金</td><td>需要配置图床（平台原生直传或自备图床）</td></tr><tr><td>GitHub 系、GitLab 系（Hexo 等）</td><td>需要配置图床</td></tr><tr><td>MetaWeblog 系（博客园、Typecho、WordPress）</td><td>图床与平台自带都支持；配了图床优先用图床</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">想强制用平台自带上传</p><p>卸载图床插件即可。知乎这类平台不支持外链，只能用它自己的上传。</p></div><h3 id="掘金发布时提示缺少分类或标签" tabindex="-1">掘金发布时提示缺少分类或标签 <a class="header-anchor" href="#掘金发布时提示缺少分类或标签" aria-label="Permalink to &quot;掘金发布时提示缺少分类或标签&quot;">​</a></h3><p>掘金平台强制要求标签与分类。未显式设置时，插件会回退默认分类「后端」与默认标签「程序员」。</p><h3 id="掘金发布后马上预览是-404" tabindex="-1">掘金发布后马上预览是 404 <a class="header-anchor" href="#掘金发布后马上预览是-404" aria-label="Permalink to &quot;掘金发布后马上预览是 404&quot;">​</a></h3><p>掘金每篇文章都要审核。审核通过前可把链接里的 <code>/post</code> 临时改成 <code>/spost</code> 查看，或等审核通过。</p><h3 id="csdn-必须设置标签" tabindex="-1">CSDN 必须设置标签 <a class="header-anchor" href="#csdn-必须设置标签" aria-label="Permalink to &quot;CSDN 必须设置标签&quot;">​</a></h3><p>这是 CSDN 平台规定，标签不能为空。</p><h3 id="博客园外链-404-或-h1-标题被替换" tabindex="-1">博客园外链 404 或 H1 标题被替换 <a class="header-anchor" href="#博客园外链-404-或-h1-标题被替换" aria-label="Permalink to &quot;博客园外链 404 或 H1 标题被替换&quot;">​</a></h3><ul><li>外链 404：可通过调整博客园用户配置解决。</li><li>H1 标题异常：多半是发布格式选错了。博客园请使用 <strong>Markdown</strong>，不要用 HTML。</li></ul><h3 id="notion-为什么不支持更新" tabindex="-1">Notion 为什么不支持更新 <a class="header-anchor" href="#notion-为什么不支持更新" aria-label="Permalink to &quot;Notion 为什么不支持更新&quot;">​</a></h3><p>Notion 基于块结构而非整篇文档。当前实现采用「先删除再发布」的方式支持更新，因此耗时可能比普通更新久一些。</p><h3 id="微信公众号为什么不能直接登录" tabindex="-1">微信公众号为什么不能直接登录 <a class="header-anchor" href="#微信公众号为什么不能直接登录" aria-label="Permalink to &quot;微信公众号为什么不能直接登录&quot;">​</a></h3><p>微信在 Electron 上有登录限制。请自行访问 <code>https://mp.weixin.qq.com/</code> 登录，然后复制 Cookie 粘贴到配置项。</p><h2 id="发布记录" tabindex="-1">发布记录 <a class="header-anchor" href="#发布记录" aria-label="Permalink to &quot;发布记录&quot;">​</a></h2><h3 id="平台上有文章-插件却显示「未发布」" tabindex="-1">平台上有文章，插件却显示「未发布」 <a class="header-anchor" href="#平台上有文章-插件却显示「未发布」" aria-label="Permalink to &quot;平台上有文章，插件却显示「未发布」&quot;">​</a></h3><p>多半是<strong>文档 ID 变了</strong>。发布记录按思源的文档 ID 保存，以下操作会改变它：</p><ul><li>删除文档后重新创建</li><li>拆分或合并文档</li><li>从别的工作区导入</li></ul><p>ID 一变，原记录就找不到这篇文档，于是显示「未发布」——但平台上的文章还在。</p><p><strong>不要直接重新发布</strong>，那会产生重复文章。改用<strong>设置 → 发布修复</strong>把两边重新对上，做法见<a href="./settings.html#发布修复">发布设置</a>。</p><h3 id="「发布修复」里的文章-id-从哪里找" tabindex="-1">「发布修复」里的文章 ID 从哪里找 <a class="header-anchor" href="#「发布修复」里的文章-id-从哪里找" aria-label="Permalink to &quot;「发布修复」里的文章 ID 从哪里找&quot;">​</a></h3><p>打开平台上的那篇文章，地址栏里通常就带着它：</p><table tabindex="0"><thead><tr><th>平台类型</th><th>位置</th></tr></thead><tbody><tr><td>多数博客平台</td><td>地址栏里的数字或 slug</td></tr><tr><td>GitHub / GitLab 系</td><td>仓库中该文章的路径或 slug</td></tr><tr><td>网页授权平台</td><td>文章编辑页的地址栏</td></tr></tbody></table><p>找不到也没关系：留空保存即可，原有记录不会被清掉，只是「查看文章」的链接可能不准。</p><h3 id="删除了旧文章后想重新发布" tabindex="-1">删除了旧文章后想重新发布 <a class="header-anchor" href="#删除了旧文章后想重新发布" aria-label="Permalink to &quot;删除了旧文章后想重新发布&quot;">​</a></h3><p>在文章管理里找到该文档，先「强制删除」清掉本地记录，再重新发布。这与「发布修复」是两件事：前者丢弃旧记录，后者把旧记录接回新文档。</p><h2 id="菜单与入口" tabindex="-1">菜单与入口 <a class="header-anchor" href="#菜单与入口" aria-label="Permalink to &quot;菜单与入口&quot;">​</a></h2><h3 id="菜单开关怎么用" tabindex="-1">菜单开关怎么用 <a class="header-anchor" href="#菜单开关怎么用" aria-label="Permalink to &quot;菜单开关怎么用&quot;">​</a></h3><p>「顶栏菜单」开关实时生效；「文档菜单」需要重新加载插件或重开思源后生效。</p><h2 id="还有问题" tabindex="-1">还有问题 <a class="header-anchor" href="#还有问题" aria-label="Permalink to &quot;还有问题&quot;">​</a></h2><ul><li>到 <a href="https://github.com/terwer/siyuan-plugin-publisher/issues" target="_blank" rel="noreferrer">GitHub Issues</a> 反馈，附上错误提示与诊断信息</li><li>提问前先看<a href="/siyuan-plugin-publisher/platforms/">平台支持</a>，每个平台都有单独的配置指南</li></ul>',59)])])}const b=t(i,[["render",l]]);export{p as __pageData,b as default};
